import { test } from "node:test";
import assert from "node:assert/strict";
import { canShip } from "../src/deploy.ts";

test("blocks deploys on Saturday", () => {
  const saturday = new Date("2026-11-21T14:00:00Z");
  assert.equal(canShip(saturday), false);
});

test("blocks deploys on Sunday", () => {
  const sunday = new Date("2026-11-22T14:00:00Z");
  assert.equal(canShip(sunday), false);
});

test("allows deploys on Monday during business hours", () => {
  const monday = new Date("2026-11-23T14:00:00Z");
  assert.equal(canShip(monday), true);
});

test("blocks deploys on Monday before business hours", () => {
  const monday = new Date("2026-11-23T08:00:00Z");
  assert.equal(canShip(monday), false);
});

test("blocks deploys on Monday after business hours", () => {
  const monday = new Date("2026-11-23T19:00:00Z");
  assert.equal(canShip(monday), false);
});

test("allows deploys on Thursday during business hours", () => {
  const thursday = new Date("2026-11-26T15:00:00Z");
  assert.equal(canShip(thursday), true);
});

test("allows deploys on Friday morning", () => {
  const friday = new Date("2026-11-27T10:00:00Z");
  assert.equal(canShip(friday), true);
});

test("blocks deploys on Friday afternoon", () => {
  const friday = new Date("2026-11-27T15:00:00Z");
  assert.equal(canShip(friday), false);
});

test("blocks deploys at Friday cutoff (2 PM)", () => {
  const friday = new Date("2026-11-27T14:00:00Z");
  assert.equal(canShip(friday), false);
});

test("allows deploys just before Friday cutoff", () => {
  const friday = new Date("2026-11-27T13:59:00Z");
  assert.equal(canShip(friday), true);
});

